import{u as p,C as l,o as n,c as d,j as t,a as o,E as r,k as c,e as h,al as a}from"./chunks/framework.7vp1BMOE.js";const f={key:0},_=JSON.parse('{"title":"PX4-Autopilot v1.17.0 Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"ko/releases/1.17.md","filePath":"ko/releases/1.17.md"}'),m={name:"ko/releases/1.17.md"},A=Object.assign(m,{setup(g){const{site:s}=p();return(b,e)=>{const i=l("Badge"),u=l("Redirect");return n(),d("div",null,[e[12]||(e[12]=t("h1",{id:"px4-autopilot-v1-17-0-release-notes",tabindex:"-1"},[o("PX4-Autopilot v1.17.0 Release Notes "),t("a",{class:"header-anchor",href:"#px4-autopilot-v1-17-0-release-notes","aria-label":'Permalink to "PX4-Autopilot v1.17.0 Release Notes"'},"​")],-1)),r(i,{type:"info",text:"Stable"}),c(s).title!=="PX4 Guide (main)"?(n(),d("div",f,[e[0]||(e[0]=t("div",{class:"custom-block danger"},[t("p",{class:"custom-block-title"},[o("This page is on a release branch, and hence probably out of date. "),t("a",{href:"https://docs.px4.io/main/en/releases/1.17"},"See the latest version"),o(".")])],-1)),r(u,{to:"https://docs.px4.io/main/en/releases/1.17"})])):h("",!0),e[13]||(e[13]=a('<p>PX4 v1.17 builds on <a href="./../releases/1.16">PX4 v1.16</a>, with the changes below landing since v1.16.2. This release adds <a href="./../flight_modes_mc/altitude_cruise">Altitude Cruise</a> mode, improves Fixed Wing Takeoff behaviour on navigation loss, and exposes cleaner high-level fixed-wing and rover control interfaces for ROS 2 workflows. The in-tree Zenoh middleware matures to <code>rmw_zenoh</code> compatibility, simulation gains Gazebo Jetty support and Ackermann SIH, and three new INS drivers (MicroStrain, sbgECom, EULER-NAV) join the ecosystem alongside Septentrio GNSS resilience reporting and barometer auto-calibration against GNSS height. PX4 v1.17 also includes user-visible MAVLink, RC, logging, failsafe, and rover refinements across the stack.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 v1.17 is documented on an alpha/beta release branch. See <a href="./../releases/main">PX4-Autopilot <code>main</code> Release Notes</a> for newer changes on <code>main</code>.</p></div><h2 id="read-before-upgrading" tabindex="-1">Read Before Upgrading <a class="header-anchor" href="#read-before-upgrading" aria-label="Permalink to &quot;Read Before Upgrading&quot;">​</a></h2><p>Please continue reading for <a href="#upgrade-guide">upgrade instructions</a>.</p><h2 id="major-changes" tabindex="-1">Major Changes <a class="header-anchor" href="#major-changes" aria-label="Permalink to &quot;Major Changes&quot;">​</a></h2>',5)),t("ul",null,[e[11]||(e[11]=a('<li>New multicopter flight mode: <a href="./../flight_modes_mc/altitude_cruise">Altitude Cruise</a>. Holds tilt and heading on stick release so the vehicle keeps cruising at a steady velocity instead of stopping like Altitude mode does.</li><li><a href="./../flight_modes_fw/takeoff">Fixed Wing Takeoff mode</a> now keeps climbing with level wings on navigation loss and can use the takeoff waypoint latitude and longitude to define the loiter position. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25226" target="_blank" rel="noreferrer">PX4-Autopilot#25226</a>)</li><li>Fixed-wing vehicles (and VTOLs in fixed-wing mode) can now be controlled from ROS 2 via the new <a href="./../ros2/px4_ros2_control_interface#fw-lateral-longitudinal-setpoint"><code>FwLateralLongitudinalSetpointType</code></a> in the PX4 ROS 2 Control Interface, exposing direct lateral and longitudinal setpoints.</li><li>Rovers can now be controlled from ROS 2 via the new <a href="./../ros2/px4_ros2_control_interface#rover-setpoints"><code>RoverSetpointTypes</code></a> in the PX4 ROS 2 Control Interface, with valid combinations of position, speed, throttle, attitude, rate, and steering setpoints exposed as guaranteed-valid setpoint types. See <a href="./../flight_modes_rover/api">Rovers Apps &amp; API</a>.</li>',4)),t("li",null,[r(i,{type:"warning",text:"Experimental"}),e[1]||(e[1]=a(' The in-tree <a href="./../middleware/zenoh">Zenoh middleware</a> matures to <code>rmw_zenoh</code> compatibility (CDRv1 serialization, ROS 2 graph liveliness, auto-generated config from <code>dds_topics.yaml</code>, Domain ID parameter, Zenoh CLI). Zenoh is built into the default firmware on FMU-v6xRT (<code>make px4_fmu-v6xrt_default</code>); on FMU-v6x and SITL it ships as a <code>zenoh</code> build variant (<code>make px4_fmu-v6x_zenoh</code>, <code>make px4_sitl_zenoh</code>).',15))]),t("li",null,[r(i,{type:"warning",text:"Experimental"}),e[2]||(e[2]=o(" Initial ",-1)),e[3]||(e[3]=t("a",{href:"./../neural_networks/mc_neural_network_control"},"MC Neural Network Control",-1)),e[4]||(e[4]=o(" test path: PX4 v1.17 integrates ",-1)),e[5]||(e[5]=t("a",{href:"./../neural_networks/tflm"},"TensorFlow Lite Micro",-1)),e[6]||(e[6]=o(" on-device so an externally trained network (for example trained with reinforcement learning in ",-1)),e[7]||(e[7]=t("a",{href:"https://ntnu-arl.github.io/aerial_gym_simulator/",target:"_blank",rel:"noreferrer"},"Aerial Gym",-1)),e[8]||(e[8]=o(") can be loaded as a tflite model and substituted for the multicopter controller for research and bench testing. It is not a replacement for the production controller stack.(",-1)),e[9]||(e[9]=t("a",{href:"https://github.com/PX4/PX4-Autopilot/pull/24366",target:"_blank",rel:"noreferrer"},"PX4-Autopilot#24366",-1)),e[10]||(e[10]=o(")",-1))])]),e[14]||(e[14]=a('<h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h2><p>For users upgrading from v1.16, please take a moment to review the following before flying:</p><ol><li><p><strong>Re-check RC stick deadzones.</strong> The hardcoded 1 percent deadzone on RC channels 1 to 8 has been removed. If your transmitter has any centre-stick jitter, configure a per-channel deadzone explicitly via <code>RC&lt;N&gt;_DZ</code> after upgrading, otherwise the vehicle may respond to small stick noise that v1.16 quietly ignored. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25502" target="_blank" rel="noreferrer">PX4-Autopilot#25502</a>)</p></li><li><p><strong>Re-trim servos with the new <code>PWM_*_CENTER</code> parameters.</strong> The old <code>PWM_*_TRIM</code> servo trim parameters have been replaced by <code>PWM_*_CENTER</code> with asymmetric deflection. Trim values are not auto-migrated. Open the actuator configuration in QGC after upgrade and re-set the centre for each servo channel that previously used <code>PWM_*_TRIM</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25897" target="_blank" rel="noreferrer">PX4-Autopilot#25897</a>)</p></li><li><p><strong>Update your GCS or companion if it relies on MAVLink v1.</strong><a href="./../advanced_config/parameter_reference#MAV_PROTO_VER"><code>MAV_PROTO_VER</code></a> now defaults to <code>2</code>. MAVLink v1 is still available, but only as an explicit opt-in. If your ground station, telemetry radio, or companion computer link was implicitly relying on the v1 fallback, either update the GCS/companion to MAVLink v2 or set <code>MAV_PROTO_VER=1</code> on the affected channel. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25583" target="_blank" rel="noreferrer">PX4-Autopilot#25583</a>)</p></li><li><p><strong>Migrate manual-control expo and deadzone parameters.</strong><code>MPC_XY_MAN_EXPO</code>, <code>MPC_Z_MAN_EXPO</code>, and <code>MPC_YAW_MAN_EXPO</code> are removed and fall back to a fixed default. <code>MPC_HOLD_DZ</code> has been renamed to <a href="./../advanced_config/parameter_reference#MAN_DEADZONE"><code>MAN_DEADZONE</code></a> and now applies globally across modes that allow a deadzone. If you previously tuned expo or hold deadzone, set <a href="./../advanced_config/parameter_reference#MAN_DEADZONE"><code>MAN_DEADZONE</code></a> explicitly; expo customisation is no longer available.</p></li><li><p><strong>Confirm barometer auto-calibration behaviour matches your setup.</strong> The new <a href="./../advanced_config/parameter_reference#SENS_BAR_AUTOCAL"><code>SENS_BAR_AUTOCAL</code></a> parameter enables barometer offset calibration against GNSS height when GNSS is the height reference, and is <strong>enabled by default</strong>. This is the desired behaviour for typical outdoor flight; if you operate indoor or in heavily GNSS-degraded environments and want to keep baro offsets locked, disable <code>SENS_BAR_AUTOCAL</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24859" target="_blank" rel="noreferrer">PX4-Autopilot#24859</a>)</p></li><li><p><strong>Re-tune range finder range-aid if you depended on <code>EKF2_RNG_A_IGATE</code>.</strong><code>EKF2_RNG_A_IGATE</code> has been removed as part of the EKF2 parameter-naming consistency refactor. Range-aid tuning now relies on the remaining <code>EKF2_RNG_A_*</code> parameters. The default <a href="./../advanced_config/parameter_reference#EKF2_MIN_RNG"><code>EKF2_MIN_RNG</code></a> was also reduced from 0.1 m to 0.01 m. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25137" target="_blank" rel="noreferrer">PX4-Autopilot#25137</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/25574" target="_blank" rel="noreferrer">PX4-Autopilot#25574</a>)</p></li><li><p><strong>Verify magnetometer configuration.</strong> Magnetometer calibration is only allowed when at least one mag is available and enabled (priority not 0). If you previously disabled all mags via priority 0, you must enable at least one before running calibration. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25714" target="_blank" rel="noreferrer">PX4-Autopilot#25714</a>)</p></li><li><p><strong>Check airframe selection.</strong><code>SYS_AUTOSTART=0</code> is now treated the same as no valid airframe. If you relied on <code>SYS_AUTOSTART=0</code> for any custom workflow, select an explicit airframe. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25645" target="_blank" rel="noreferrer">PX4-Autopilot#25645</a>)</p></li><li><p><strong>Update scripts and external tooling for renamed commander/termination interfaces.</strong> The <code>commander lockdown on</code> shell command is now <code>commander termination</code>. The <code>FORCE_FAILSAFE</code> action is now <code>TERMINATION</code>, and <code>manual_lockdown</code> is now <code>kill</code>. Update any startup scripts, test harnesses, or external tooling that calls these by name.</p></li><li><p><strong>Migrate consumers of <code>battery_status.serial_number</code>.</strong> The <code>serial_number</code> field has moved from <code>battery_status</code> to a new <code>battery_info</code> uORB message. Any consumer (logger, GCS, companion software) reading the serial number from <code>battery_status</code> must subscribe to <code>battery_info</code> instead.</p></li><li><p><strong>Remove <code>parameters_injected.xml</code> from custom build flows.</strong><code>parameters_injected.xml</code> has been removed from the build system. If you maintained a board layer or downstream fork that referenced it, drop the reference. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25549" target="_blank" rel="noreferrer">PX4-Autopilot#25549</a>)</p></li></ol><h2 id="other-changes" tabindex="-1">Other changes <a class="header-anchor" href="#other-changes" aria-label="Permalink to &quot;Other changes&quot;">​</a></h2><h3 id="hardware-support" tabindex="-1">Hardware Support <a class="header-anchor" href="#hardware-support" aria-label="Permalink to &quot;Hardware Support&quot;">​</a></h3><h4 id="new-flight-controllers" tabindex="-1">New Flight Controllers <a class="header-anchor" href="#new-flight-controllers" aria-label="Permalink to &quot;New Flight Controllers&quot;">​</a></h4><ul><li><a href="./../flight_controller/radiolink_pix6">Radiolink PIX6</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25562" target="_blank" rel="noreferrer">PX4-Autopilot#25562</a>)</li><li><a href="./../flight_controller/cuav_x25-evo">CUAV X25-Evo</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25176" target="_blank" rel="noreferrer">PX4-Autopilot#25176</a>)</li><li><a href="./../flight_controller/accton-godwit_ga1">Accton Godwit GA1</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25411" target="_blank" rel="noreferrer">PX4-Autopilot#25411</a>)</li><li>Kakute H7 dual-IMU build target (no English docs page).</li><li>NarinFC-H7 (no English docs page).</li><li>ESP32 generic-target support, sponsored by AutonoSky (no English docs page; experimental).</li></ul><h4 id="new-build-targets-for-existing-hardware" tabindex="-1">New Build Targets for Existing Hardware <a class="header-anchor" href="#new-build-targets-for-existing-hardware" aria-label="Permalink to &quot;New Build Targets for Existing Hardware&quot;">​</a></h4><ul><li><code>cuav/fmu-v6x</code> build target for the <a href="./../flight_controller/cuav_pixhawk_v6x">CUAV Pixhawk V6X</a>.</li><li><code>auterion/fmu-v6x</code> build target for the Auterion FMU-v6x.</li></ul><h4 id="new-can-peripherals-vehicle-platforms" tabindex="-1">New CAN Peripherals &amp; Vehicle Platforms <a class="header-anchor" href="#new-can-peripherals-vehicle-platforms" aria-label="Permalink to &quot;New CAN Peripherals &amp; Vehicle Platforms&quot;">​</a></h4><ul><li>MR-CANHUBK344 NXP B3RB Rover platform. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23897" target="_blank" rel="noreferrer">PX4-Autopilot#23897</a>)</li><li>NXP MR-Tropic target with imxrt-related fixes. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26052" target="_blank" rel="noreferrer">PX4-Autopilot#26052</a>)</li><li>ARK X20 and F9P GPS receivers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25149" target="_blank" rel="noreferrer">PX4-Autopilot#25149</a>)</li><li>ARK DIST distance sensor.</li></ul><h4 id="existing-boards-improvements" tabindex="-1">Existing Boards: Improvements <a class="header-anchor" href="#existing-boards-improvements" aria-label="Permalink to &quot;Existing Boards: Improvements&quot;">​</a></h4><ul><li>FMU-v6xRT: V6XRT001 and V6XRT002 sensor sets, LIS2MDL and BMM350 magnetometer support, DTCM added to heap. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25733" target="_blank" rel="noreferrer">PX4-Autopilot#25733</a>)</li><li>FMU-v6s: PCA9685 PWM expander driver, INA226 / INA228 / INA238 power-monitor support, HSE used as the RTC clock, init script reordered to start internal sensors first.</li><li>ARK FPV: rover board variant, payload-deliverer module, and <code>encrypted_logs</code> flash savings (FW and VTOL stripped). (<a href="https://github.com/PX4/PX4-Autopilot/pull/25319" target="_blank" rel="noreferrer">PX4-Autopilot#25319</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/25322" target="_blank" rel="noreferrer">PX4-Autopilot#25322</a>)</li><li>ARK SCH16T driver updated for new Murata modules. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24029" target="_blank" rel="noreferrer">PX4-Autopilot#24029</a>)</li><li>mRO PixracerPro: enable additional UARTs. (<a href="https://github.com/PX4/PX4-Autopilot/pull/22516" target="_blank" rel="noreferrer">PX4-Autopilot#22516</a>)</li><li>3DR Control Zero H7 OEM Rev G: MTD driver fix and missing module that prevented USB enumeration. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25015" target="_blank" rel="noreferrer">PX4-Autopilot#25015</a>)</li><li>ESP32: PWM register updates correctly on change. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25653" target="_blank" rel="noreferrer">PX4-Autopilot#25653</a>)</li><li>Tropic-Community baseboard (Teensy 4.1): PX4 config refresh, DTCM moved to heap with vectors in ITCM.</li></ul><h3 id="공통" tabindex="-1">공통 <a class="header-anchor" href="#공통" aria-label="Permalink to &quot;공통&quot;">​</a></h3><ul><li><a href="./../advanced_config/bootloader_update#qgc-bootloader-update-sys-bl-update">QGC Bootloader Update</a> via the <a href="./../advanced_config/parameter_reference#SYS_BL_UPDATE"><code>SYS_BL_UPDATE</code></a> parameter has been re-enabled after being broken for several releases. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25032" target="_blank" rel="noreferrer">PX4-Autopilot#25032</a>)</li><li>Failsafe handling now lets the pilot take over from a degraded failsafe state. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26269" target="_blank" rel="noreferrer">PX4-Autopilot#26269</a>)</li><li>Offboard to Position (hold) mode change is no longer entered without RC. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26391" target="_blank" rel="noreferrer">PX4-Autopilot#26391</a>)</li><li>Motor failure detection uses more robust timeout checks. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25757" target="_blank" rel="noreferrer">PX4-Autopilot#25757</a>)</li><li>New <code>battery_info</code> uORB message with serial number compatible with UAVCAN, MAVLink, and battery drivers; <code>battery_status.serial_number</code> is removed.</li><li>UAVCAN battery: better remaining-time calculation (<a href="https://github.com/PX4/PX4-Autopilot/pull/25500" target="_blank" rel="noreferrer">PX4-Autopilot#25500</a>) and filter sample interval increased to 500 ms (<a href="https://github.com/PX4/PX4-Autopilot/pull/25454" target="_blank" rel="noreferrer">PX4-Autopilot#25454</a>).</li><li>Battery instances are capped at 3 (loggable batteries also raised to 3).</li><li>Remaining-flight-time failsafe disabled by default.</li><li>Removed parameter <code>COM_RC_ARM_HYST</code>, arm and disarm gesture needs to be held for the default of one second. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25999" target="_blank" rel="noreferrer">PX4-Autopilot#25999</a>)</li></ul><h3 id="제어" tabindex="-1">제어 <a class="header-anchor" href="#제어" aria-label="Permalink to &quot;제어&quot;">​</a></h3><ul><li>Servo PWM gains center setting and asymmetric deflection (<code>PWM_*_CENTER</code>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/25897" target="_blank" rel="noreferrer">PX4-Autopilot#25897</a>)</li><li>PWM center support extended to wheel and gimbal actuators. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26211" target="_blank" rel="noreferrer">PX4-Autopilot#26211</a>)</li><li>Configurable board PWM frequency from Kconfig. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24787" target="_blank" rel="noreferrer">PX4-Autopilot#24787</a>)</li><li>DShot telemetry refactored to the platform serial abstraction with RX/TX pin-swap support.</li><li>UAVCAN ESC initialization no longer publishes random values when stopped. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25485" target="_blank" rel="noreferrer">PX4-Autopilot#25485</a>)</li><li>UAVCAN bootloader watchdog pet during long flashes. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25523" target="_blank" rel="noreferrer">PX4-Autopilot#25523</a>)</li><li>Control allocator enabled for spacecraft on v6x. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25276" target="_blank" rel="noreferrer">PX4-Autopilot#25276</a>)</li></ul><h3 id="estimation" tabindex="-1">Estimation <a class="header-anchor" href="#estimation" aria-label="Permalink to &quot;Estimation&quot;">​</a></h3><ul><li><a href="./../advanced_config/parameter_reference#SENS_BAR_AUTOCAL">Barometer auto-calibration</a> can calibrate offsets against GNSS height when GNSS is the height reference, enabled by default. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24859" target="_blank" rel="noreferrer">PX4-Autopilot#24859</a>)</li><li>Septentrio GNSS resilience reporting (jamming, spoofing, authentication state) is now exposed in PX4. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25012" target="_blank" rel="noreferrer">PX4-Autopilot#25012</a>)</li><li>EKF2 GPS checks include a GPS fix type validation bit. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25215" target="_blank" rel="noreferrer">PX4-Autopilot#25215</a>)</li><li>EKF2 GNSS aiding: dedicated <code>gnss_fault</code> flag added to <code>EstimatorStatusFlags</code>; lat/lon/vel fusion is disabled on <code>gnss_hgt_fault</code>; hysteresis added for re-enabling fusion; GNSS-based altitude reset is suppressed in dead-reckoning mode.</li><li>EKF2 range fusion: skip unhealthy samples while respecting timeout (<a href="https://github.com/PX4/PX4-Autopilot/pull/25634" target="_blank" rel="noreferrer">PX4-Autopilot#25634</a>); reject bad measurements during <code>bad_acc_vertical</code> (<a href="https://github.com/PX4/PX4-Autopilot/pull/25636" target="_blank" rel="noreferrer">PX4-Autopilot#25636</a>).</li><li>EKF2 mag: post-takeoff yaw reset is never skipped; mag heading and declination updates no longer perturb the xy gyro biases.</li><li>EKF2 gravity: tilt alignment accelerated; gravity fusion start now uses an accel low-pass instead of peak hold.</li><li>EKF2 airspeed/wind: distinguish airspeed source so wind dead-reckoning logic can use a synthetic airspeed.</li><li>External heading update via <code>MAV_CMD_EXTERNAL_ATTITUDE_ESTIMATE</code> is now consumed by EKF2.</li><li>RTCM telemetry stream now also published for UAVCAN GNSS receivers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25315" target="_blank" rel="noreferrer">PX4-Autopilot#25315</a>)</li><li>EKF2 GNSS reset improvements. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25297" target="_blank" rel="noreferrer">PX4-Autopilot#25297</a>)</li></ul><h3 id="센서" tabindex="-1">센서 <a class="header-anchor" href="#센서" aria-label="Permalink to &quot;센서&quot;">​</a></h3><ul><li>Added <a href="./../sensor/microstrain">MicroStrain Inertial Sensors</a> driver support. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23858" target="_blank" rel="noreferrer">PX4-Autopilot#23858</a>)</li><li><a href="./../sensor/microstrain">MicroStrain Inertial Sensors</a> gain expanded aiding support. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25673" target="_blank" rel="noreferrer">PX4-Autopilot#25673</a>)</li><li>Added <a href="./../sensor/sbgecom">sbgECom INS driver</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24137" target="_blank" rel="noreferrer">PX4-Autopilot#24137</a>)</li><li>Added EULER-NAV Baro-Inertial AHRS driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24534" target="_blank" rel="noreferrer">PX4-Autopilot#24534</a>)</li><li>Added QMC5883P compass driver. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25115" target="_blank" rel="noreferrer">PX4-Autopilot#25115</a>)</li><li>Added ICM42688P IMU support on the Mamba F405 MK2 V2. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25047" target="_blank" rel="noreferrer">PX4-Autopilot#25047</a>)</li><li>Added LightWare SF30/d binary protocol. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25570" target="_blank" rel="noreferrer">PX4-Autopilot#25570</a>)</li><li>Airspeed calibration only saves the offset when the full procedure succeeds. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25412" target="_blank" rel="noreferrer">PX4-Autopilot#25412</a>)</li><li>AirspeedSelector adds a synthetic airspeed option.</li><li>IMU gyro: default angular-acceleration filter lowered from 30 Hz to 20 Hz.</li></ul><h3 id="시뮬레이션" tabindex="-1">시뮬레이션 <a class="header-anchor" href="#시뮬레이션" aria-label="Permalink to &quot;시뮬레이션&quot;">​</a></h3><h4 id="gazebo" tabindex="-1">Gazebo <a class="header-anchor" href="#gazebo" aria-label="Permalink to &quot;Gazebo&quot;">​</a></h4><ul><li>Gazebo CMake linking is now version-agnostic across <code>gz-transport</code>, <code>gz-sim</code>, <code>gz-sensors</code>, and <code>gz-plugin</code>, removing the hard pin to Harmonic in the build glue. Harmonic remains the supported, CI-tested version; building against newer Gazebo releases (e.g. Jetty / v15) is up to the developer to install and verify locally. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25521" target="_blank" rel="noreferrer">PX4-Autopilot#25521</a>)</li><li><a href="./../frames_rover/#simulation">Rover simulation</a> updated to match the current rover-control architecture. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25644" target="_blank" rel="noreferrer">PX4-Autopilot#25644</a>)</li><li>Gazebo bridge sensors can be selectively disabled. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25484" target="_blank" rel="noreferrer">PX4-Autopilot#25484</a>)</li><li>Gimbal yaw fix and DDS attitude publisher in the Gazebo bridge. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25754" target="_blank" rel="noreferrer">PX4-Autopilot#25754</a>)</li><li><code>PX4_GZ_MODEL_POSE</code> for custom spawn pose. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24956" target="_blank" rel="noreferrer">PX4-Autopilot#24956</a>)</li><li>Updated Gazebo 24.04 documentation. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25586" target="_blank" rel="noreferrer">PX4-Autopilot#25586</a>)</li></ul><h4 id="simulation-in-hardware-sih" tabindex="-1">Simulation-in-Hardware (SIH) <a class="header-anchor" href="#simulation-in-hardware-sih" aria-label="Permalink to &quot;Simulation-in-Hardware (SIH)&quot;">​</a></h4><ul><li><a href="./../sim_sih/#supported-vehicle-types">SIH</a> now supports Hexacopter X and Ackermann rovers. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25194" target="_blank" rel="noreferrer">PX4-Autopilot#25194</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/25405" target="_blank" rel="noreferrer">PX4-Autopilot#25405</a>)</li><li>HITL/SIH battery status now driven by battery configuration parameters. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24103" target="_blank" rel="noreferrer">PX4-Autopilot#24103</a>)</li></ul><h3 id="debug-logging" tabindex="-1">Debug &amp; Logging <a class="header-anchor" href="#debug-logging" aria-label="Permalink to &quot;Debug &amp; Logging&quot;">​</a></h3><ul><li><code>AirspeedValidated</code> promoted to a standard uORB topic. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25579" target="_blank" rel="noreferrer">PX4-Autopilot#25579</a>)</li><li><code>upload_log.py</code> can target a custom upload server via CLI argument. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25702" target="_blank" rel="noreferrer">PX4-Autopilot#25702</a>)</li><li>ULog tooling can recover UTC timestamps even when <code>sensor_gps</code> is not present. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25534" target="_blank" rel="noreferrer">PX4-Autopilot#25534</a>)</li><li>UAVCAN node status is now logged to uORB for debugging. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23890" target="_blank" rel="noreferrer">PX4-Autopilot#23890</a>)</li><li>ULog file format documentation expanded. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25624" target="_blank" rel="noreferrer">PX4-Autopilot#25624</a>)</li></ul><h3 id="ros-2-uxrce-dds" tabindex="-1">ROS 2 / uXRCE-DDS <a class="header-anchor" href="#ros-2-uxrce-dds" aria-label="Permalink to &quot;ROS 2 / uXRCE-DDS&quot;">​</a></h3><ul><li><a href="./../ros2/px4_ros2_control_interface">PX4 ROS 2 Control Interface</a> support for <a href="./../ros2/px4_ros2_control_interface#fw-lateral-longitudinal-setpoint">Fixed Wing lateral and longitudinal setpoint</a> and <a href="./../ros2/px4_ros2_control_interface#controlling-a-vtol">VTOL transitions</a>.</li><li><a href="./../middleware/uxrce_dds#customizing-the-namespace">Simple index-based namespace (<code>UXRCE_DDS_NS_IDX</code>)</a> for uXRCE-DDS. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25444" target="_blank" rel="noreferrer">PX4-Autopilot#25444</a>)</li><li>Namespace support for the uXRCE-DDS client during firmware upload. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25291" target="_blank" rel="noreferrer">PX4-Autopilot#25291</a>)</li><li>New DDS topics: <code>TransponderReport</code> (ADS-B) (<a href="https://github.com/PX4/PX4-Autopilot/pull/25652" target="_blank" rel="noreferrer">PX4-Autopilot#25652</a>), <code>landing_gear</code> command from external modes (<a href="https://github.com/PX4/PX4-Autopilot/pull/25496" target="_blank" rel="noreferrer">PX4-Autopilot#25496</a>), <code>Wind</code> topic with 1 Hz rate limit, gimbal device attitude status, and FW high-level setpoint/configuration interfaces.</li></ul><h3 id="ros-2-zenoh" tabindex="-1">ROS 2 / Zenoh <a class="header-anchor" href="#ros-2-zenoh" aria-label="Permalink to &quot;ROS 2 / Zenoh&quot;">​</a></h3>',31)),r(i,{type:"warning",text:"Experimental"}),e[15]||(e[15]=a('<p>The in-tree <a href="./../middleware/zenoh">Zenoh middleware</a> (added in v1.16) matures toward <code>rmw_zenoh</code> compatibility in v1.17. Most of this work landed as direct commits without PR numbers; the following list groups it by area:</p><ul><li><strong>rmw_zenoh compatibility</strong>: implement <code>rmw_zenoh</code> features in the Zenoh module, move ROS 2 Rmw attachment code to <code>rmw_attachment.h</code>, switch to CDRv1 to match ROS 2, set transport lease to 60 s to match ROS 2, omit timestamp attachment, experimental liveliness so the ROS 2 graph works.</li><li><strong>Configuration and CLI</strong>: auto-generate default Zenoh config from <code>dds_topics.yaml</code>, new Domain ID parameter (and move <code>gid</code> into Zenoh), Zenoh CLI improvements, instance selection and pub/sub deletion, copy the uXRCE config layout for Zenoh.</li><li><strong>Boards</strong>: Zenoh is now built into the default firmware on <code>px4/fmu-v6xrt</code> (<code>make px4_fmu-v6xrt_default</code>). On <code>px4/fmu-v6x</code> and SITL it ships as an opt-in <code>zenoh</code> build variant (<code>make px4_fmu-v6x_zenoh</code>, <code>make px4_sitl_zenoh</code>); the same opt-in <code>zenoh.px4board</code> is also provided for <code>auterion/fmu-v6s</code> and <code>auterion/fmu-v6x</code>. Zenoh is additionally compiled in by default on <code>nxp/mr-canhubk3</code>, <code>nxp/mr-tropic</code>, and <code>nxp/tropic-community</code>.</li><li><strong>NuttX support</strong>: update NuttX config for use with Zenoh; backport NuttX FMU-v6x config for Zenoh (<a href="https://github.com/PX4/PX4-Autopilot/pull/26213" target="_blank" rel="noreferrer">PX4-Autopilot#26213</a>).</li><li><strong>SITL</strong>: new <code>px4_sitl_zenoh</code> cmake variant, default to <code>127.0.0.1</code> on SITL/POSIX, autostart Zenoh in SITL when enabled, friendlier error message when scouting finds nothing, GCC/SITL compile fixes.</li><li><strong>Robustness</strong>: validate payload size before stack allocation, increase CDR safety margin, handle parsing errors and non-existing types in config, fix topic-name and datatype mapping, pubsub-factory datatype-naming fix, fix status <code>keyexpr</code> printf, prevent integer-conversion warnings in zenoh-pico, optimize memory usage with optional publish-on-matching.</li><li><strong>Docs and OOM fixes (backport)</strong>: <a href="https://github.com/PX4/PX4-Autopilot/pull/26053" target="_blank" rel="noreferrer">PX4-Autopilot#26053</a>.</li><li><strong>Submodule</strong>: <code>zenoh-pico</code> updated.</li></ul><h3 id="mavlink" tabindex="-1">MAVLink <a class="header-anchor" href="#mavlink" aria-label="Permalink to &quot;MAVLink&quot;">​</a></h3><ul><li>MAVFTP hardening: rejects path-traversal sequences in FTP operations and validates sessions in FTP write/burst.</li><li>MAVLink v1 is now opt-in via <a href="./../advanced_config/parameter_reference#MAV_PROTO_VER"><code>MAV_PROTO_VER</code></a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25583" target="_blank" rel="noreferrer">PX4-Autopilot#25583</a>)</li><li>Extended <code>MISSION_CURRENT</code> message implemented (populates <code>mission_state</code> and related fields per <a href="https://github.com/mavlink/mavlink/pull/1869" target="_blank" rel="noreferrer">mavlink/mavlink#1869</a>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/25034" target="_blank" rel="noreferrer">PX4-Autopilot#25034</a>)</li><li><code>MAV_CMD_REQUEST_MESSAGE</code> supported for <code>MESSAGE_INTERVAL</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25460" target="_blank" rel="noreferrer">PX4-Autopilot#25460</a>)</li><li>The low-bandwidth stream profile includes additional important streams with updated rates. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25524" target="_blank" rel="noreferrer">PX4-Autopilot#25524</a>)</li><li>Parameter transmission throttled on low-bandwidth links. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25126" target="_blank" rel="noreferrer">PX4-Autopilot#25126</a>)</li><li>Set system clock from <code>SYSTEM_TIME</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24807" target="_blank" rel="noreferrer">PX4-Autopilot#24807</a>)</li><li>Hardfault streaming over MAVLink option added.</li><li>MAVLink fuzz test added.</li></ul><h3 id="rc" tabindex="-1">RC <a class="header-anchor" href="#rc" aria-label="Permalink to &quot;RC&quot;">​</a></h3><ul><li>Removed the hardcoded 1 percent deadzone on RC channels 1 to 8. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25502" target="_blank" rel="noreferrer">PX4-Autopilot#25502</a>)</li><li>ManualControlSelector reworked: robust timeout checks, unified validity conditions, simplified prioritization, and an option to prioritize RC or MAVLink with fallback.</li><li><code>COM_RC_IN_MODE</code> extended with source-ID ascending and descending priority modes; documentation rewritten.</li><li>Payload power switch generalized: optional 3-way switch, allowed on boards beyond ARK FPV, with unit tests.</li></ul><h3 id="multi-rotor" tabindex="-1">Multi-Rotor <a class="header-anchor" href="#multi-rotor" aria-label="Permalink to &quot;Multi-Rotor&quot;">​</a></h3><ul><li>New multicopter flight mode: <a href="./../flight_modes_mc/altitude_cruise">Altitude Cruise</a>. Like Altitude mode, but when the roll/pitch/yaw sticks are released the vehicle holds the current tilt and heading (rather than returning to level), letting it cruise at a steady velocity without constant stick input. Intended for long-distance flights where the same tilt is held for an extended period. The manual-control-loss failsafe can optionally be disabled for this mode by setting the corresponding bit in <a href="./../advanced_config/parameter_reference#COM_RCL_EXCEPT"><code>COM_RCL_EXCEPT</code></a>; when doing so, configure the data-link-loss failsafe via <a href="./../advanced_config/parameter_reference#NAV_DLL_ACT"><code>NAV_DLL_ACT</code></a> to avoid fly-aways.</li><li>Stick library refactored: globally available, getter-based, expo computed on getter call; <code>FixedWingModeManager</code> now uses the Sticks library.</li><li>Orbit mode: configurable max speed replaces the 10 m/s hardcode (<a href="https://github.com/PX4/PX4-Autopilot/pull/25192" target="_blank" rel="noreferrer">PX4-Autopilot#25192</a>) and <code>HeadingSmoothing</code> is applied to avoid step changes during the approach; documentation clarified (<a href="https://github.com/PX4/PX4-Autopilot/pull/25208" target="_blank" rel="noreferrer">PX4-Autopilot#25208</a>).</li><li>MC PositionControl: switch out of goto setpoint immediately when receiving <code>trajectory_setpoint</code>.</li><li>Hexarotor X added to SIH and to <code>ActuatorEffectivenessRotorsTest</code>.</li><li><code>MC_RATE*</code> parameter metadata unified. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25133" target="_blank" rel="noreferrer">PX4-Autopilot#25133</a>)</li><li>Removed parameters <code>MPC_{XY/Z/YAW}_MAN_EXPO</code> and use default value instead, as they were not deemed necessary anymore. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25435" target="_blank" rel="noreferrer">PX4-Autopilot#25435</a>).</li><li>Renamed <code>MPC_HOLD_DZ</code> to <code>MAN_DEADZONE</code> to have it globally available in modes that allow for a dead zone. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25435" target="_blank" rel="noreferrer">PX4-Autopilot#25435</a>).</li></ul><h3 id="수직이착륙기-vtol" tabindex="-1">수직이착륙기(VTOL) <a class="header-anchor" href="#수직이착륙기-vtol" aria-label="Permalink to &quot;수직이착륙기(VTOL)&quot;">​</a></h3><ul><li>Fixed VTOL stuck after back-transition in Mission Fast RTL.</li><li>VTOL takeoff requires relaxed position only during the fixed-wing phase; on completion of takeoff, the state is forced to Loiter.</li><li>VTOL airspeed measurement handling centralized.</li><li><a href="./../ros2/px4_ros2_control_interface#controlling-a-vtol">PX4 ROS 2 Control Interface</a> can command VTOL transitions from external modes.</li></ul><h3 id="fixed-wing" tabindex="-1">Fixed-wing <a class="header-anchor" href="#fixed-wing" aria-label="Permalink to &quot;Fixed-wing&quot;">​</a></h3><ul><li><a href="./../flight_modes_fw/takeoff">Fixed Wing Takeoff mode</a> keeps climbing with level wings on navigation loss and can use the takeoff waypoint latitude and longitude to define the loiter position. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25226" target="_blank" rel="noreferrer">PX4-Autopilot#25226</a>)</li><li>Reworked fixed-wing high-level control exposes clean lateral and longitudinal control interfaces for external integrations.</li><li>FW Attitude Controller wheel controller rework.</li><li>FW Autotune: identification maneuver auto-ramps the 1 Hz amplitude until R/P/Y rates of 0.8/0.5/0.5 rad/s are reached, then scales the identification signal accordingly.</li><li>TECS hardening: NaN protection on airspeed and altitude inputs.</li></ul><h3 id="rover" tabindex="-1">Rover <a class="header-anchor" href="#rover" aria-label="Permalink to &quot;Rover&quot;">​</a></h3><ul><li>Removed deprecated rover module.</li><li>Added <a href="./../flight_modes_rover/api">Apps &amp; API</a> support including <a href="./../ros2/px4_ros2_control_interface#rover-setpoints">Rover Setpoints</a>.</li><li><a href="./../frames_rover/#simulation">Rover simulation</a> updated to match the reworked rover architecture. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25644" target="_blank" rel="noreferrer">PX4-Autopilot#25644</a>)</li><li>Continued per-vehicle (Ackermann/differential/mecanum) restructuring with separated actuator control, position-control updates, mode-management centralization, and module split into folders.</li><li>New stick-input scaling parameters. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25427" target="_blank" rel="noreferrer">PX4-Autopilot#25427</a>)</li><li>Improved rover hold-position logic. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25466" target="_blank" rel="noreferrer">PX4-Autopilot#25466</a>)</li><li><code>RX_MAX_THR_YAW_R</code> replaced by <code>RO_YAW_RATE_CORR</code>.</li><li>Manual yaw-rate input: exponential scaling.</li><li>Comprehensive <a href="./../flight_modes_rover/api">Rover API documentation</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25499" target="_blank" rel="noreferrer">PX4-Autopilot#25499</a>)</li><li>MR-CANHUBK344 NXP B3RB rover platform. (<a href="https://github.com/PX4/PX4-Autopilot/pull/23897" target="_blank" rel="noreferrer">PX4-Autopilot#23897</a>)</li><li>Aion Robotics R1 Rover airframe (<code>50001</code>) marked discontinued.</li></ul><h3 id="safety-commander" tabindex="-1">Safety / Commander <a class="header-anchor" href="#safety-commander" aria-label="Permalink to &quot;Safety / Commander&quot;">​</a></h3><ul><li>Failure injection refactored into its own class; <code>failure motor off -i &lt;n&gt;</code> now requires <code>CA_FAILURE_MODE</code> to be set. See <a href="./../debug/failure_injection">motor failure injection and detection</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25756" target="_blank" rel="noreferrer">PX4-Autopilot#25756</a>)</li><li>Naming for clarity: <code>FORCE_FAILSAFE</code> renamed to <code>TERMINATION</code>; <code>commander lockdown on</code> renamed to <code>commander termination</code>; <code>manual_lockdown</code> renamed to <code>kill</code>; <code>ACTION_TERMINATE</code> renamed to <code>ACTION_TERMINATION</code>.</li><li>New RC termination switch with PWM-input default for ATS-based flight termination. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25209" target="_blank" rel="noreferrer">PX4-Autopilot#25209</a>)</li><li>Commander never overrides a user-intended termination (with unit test).</li><li>Remaining-flight-time failsafe disabled by default.</li><li>Home position is not reset if landed during an uncompleted mission. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24902" target="_blank" rel="noreferrer">PX4-Autopilot#24902</a>)</li><li>Off-track mission landing fix. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25725" target="_blank" rel="noreferrer">PX4-Autopilot#25725</a>)</li></ul><h3 id="infrastructure" tabindex="-1">Infrastructure <a class="header-anchor" href="#infrastructure" aria-label="Permalink to &quot;Infrastructure&quot;">​</a></h3><ul><li><code>parameters_injected.xml</code> removed from the build system. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25549" target="_blank" rel="noreferrer">PX4-Autopilot#25549</a>)</li><li><a href="./../advanced_config/bootloader_update#qgc-bootloader-update-sys-bl-update">QGC Bootloader Update</a> via <code>SYS_BL_UPDATE</code> restored. (<a href="https://github.com/PX4/PX4-Autopilot/pull/25032" target="_blank" rel="noreferrer">PX4-Autopilot#25032</a>)</li><li>NuttX submodule updates: dcache fix and semaphore-holder-list fix.</li><li>ITCM checker added in CI; ITCM mapping updated for v6xRT and Tropic-Community.</li><li>Flash savings on KakuteH7 encrypted-logs variants and on selected ARK targets.</li><li>Spacecraft tooling for Commander and <code>VehicleStatus</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24716" target="_blank" rel="noreferrer">PX4-Autopilot#24716</a>)</li></ul>',18))])}}});export{_ as __pageData,A as default};
